 const knownEvent=useRef<string|null>(null),current=useRef({rev:0,s:null as any}),timeoutSent=useRef(''),soundRef=useRef(false),polling=useRef(false);
 const look=s?.presentation||presentation,spec=stream||role==='viewer',adjusting=s&&s.started&&!turn(s)&&clock<s.swapDeadline,adjustSeconds=Math.max(0,Math.ceil(((s?.swapDeadline||0)-clock)/1000));
