 const name=(id:string)=>champion(id)?.name||id;
 const t=s?turn(s):null, block=s?locked(s):new Set<string>(),isCaptain=role==='B'||role==='R',canAct=s&&s.started&&!s.paused&&!change&&t&&(role===t.side||room==='demo')&&!stream;
 const voteState=s?.resultVotes||{},myVote=isCaptain?voteState[role]:null,allVotes=Boolean(voteState.B&&voteState.R),
 resultConflict=Boolean(s?.resultConflict||(allVotes&&voteState.B?.winner&&voteState.R?.winner&&(voteState.B.winner!==voteState.R.winner||voteState.B.invertSides!==voteState.R.invertSides)));
